package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"

	"github.com/bazelbuild/rules_go/go/runfiles"
)

// invocation describes the compiler action generated by the Starlark rule.
type invocation struct {
	// Compiler is an action input path or a runfile path.
	Compiler string `json:"compiler"`
	// Main is the entry point relative to the staged source tree.
	Main string `json:"main"`
	// Output is the success marker path for a check.
	Output string `json:"output"`
	// Sources maps staged paths to action input or runfile paths.
	Sources map[string]string `json:"sources"`
}

// main locates the invocation manifest and preserves Bend's exit status.
func main() {
	if err := launch(context.Background()); err != nil {
		fmt.Fprintf(os.Stderr, "rules_bend: %v\n", err)
		var exit *exec.ExitError
		if errors.As(err, &exit) && exit.ExitCode() > 0 {
			os.Exit(exit.ExitCode())
		}
		os.Exit(1)
	}
}

// launch reads the sidecar for a runnable target or the manifest argument for a check.
func launch(ctx context.Context) error {
	manifest := os.Args[0] + ".bend.json"
	data, err := os.ReadFile(manifest)
	runnable := err == nil
	if errors.Is(err, os.ErrNotExist) && len(os.Args) == 2 {
		manifest = os.Args[1]
		data, err = os.ReadFile(manifest)
	}
	if err != nil {
		return fmt.Errorf("read manifest %q: %w", manifest, err)
	}
	var action invocation
	if err := json.Unmarshal(data, &action); err != nil {
		return fmt.Errorf("decode manifest %q: %w", manifest, err)
	}
	resolve := filepath.Abs
	var environment []string
	if runnable {
		files, err := runfiles.New(runfiles.SourceRepo(""))
		if err != nil {
			return fmt.Errorf("locate Bend runfiles: %w", err)
		}
		resolve = files.Rlocation
		environment = files.Env()
	}
	if err := run(ctx, action, resolve, environment, os.Args[1:]); err != nil {
		return fmt.Errorf("invoke Bend from %q: %w", manifest, err)
	}
	return nil
}

// run stages the declared sources and runs or checks the entry point.
func run(ctx context.Context, action invocation, resolve func(string) (string, error), environment, arguments []string) (result error) {
	if _, declared := action.Sources[action.Main]; !declared {
		return fmt.Errorf("entry point %q is absent from the manifest sources", action.Main)
	}
	compiler, err := resolve(action.Compiler)
	if err != nil {
		return fmt.Errorf("resolve compiler path %q: %w", action.Compiler, err)
	}

	directory, err := os.MkdirTemp("", "bend-action-")
	if err != nil {
		return fmt.Errorf("create Bend staging directory: %w", err)
	}
	defer func() {
		if err := os.RemoveAll(directory); err != nil {
			result = errors.Join(result, fmt.Errorf("remove staging directory %q: %w", directory, err))
		}
	}()

	for destination, source := range action.Sources {
		if !filepath.IsLocal(destination) {
			return fmt.Errorf("invalid staged path %q", destination)
		}
		path, err := resolve(source)
		if err != nil {
			return fmt.Errorf("resolve source %q: %w", source, err)
		}
		if err := stage(filepath.Join(directory, destination), path); err != nil {
			return fmt.Errorf("prepare %q: %w", destination, err)
		}
	}

	args := []string{filepath.Join(directory, action.Main)}
	if action.Output != "" {
		args = append(args, "--check-only")
	} else {
		args = append(args, "--")
		args = append(args, arguments...)
	}
	command := exec.CommandContext(ctx, compiler, args...)
	command.Env = append(command.Environ(), environment...)
	command.Env = append(command.Env, "BEND_LIB="+filepath.Join(directory, "hub"))
	command.Stdin = os.Stdin
	command.Stdout = os.Stdout
	command.Stderr = os.Stderr
	if err := command.Run(); err != nil {
		return fmt.Errorf("run Bend on %q: %w", action.Main, err)
	}
	if action.Output != "" {
		if err := os.WriteFile(action.Output, []byte("checked\n"), 0o644); err != nil {
			return fmt.Errorf("write check marker %q: %w", action.Output, err)
		}
	}
	return nil
}

// stage copies a source to a regular file so Bend resolves imports inside the staging tree.
func stage(destination, source string) error {
	data, err := os.ReadFile(source)
	if err != nil {
		return fmt.Errorf("read source %q: %w", source, err)
	}
	directory := filepath.Dir(destination)
	if err := os.MkdirAll(directory, 0o755); err != nil {
		return fmt.Errorf("create source directory %q: %w", directory, err)
	}
	if err := os.WriteFile(destination, data, 0o644); err != nil {
		return fmt.Errorf("stage source %q: %w", source, err)
	}
	return nil
}
